#include <cassert>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iterator>
#include <limits>
#include <string>

struct DoubleMetrics { uint32_t version, kernels; uint64_t wall_ns; double gpu_seconds; uint64_t allocated_bytes; };
extern "C" int wxdouble_create(const char*, uint64_t, void**, char*, uint32_t);
extern "C" int wxdouble_normalize(void*, const double*, uint32_t, uint32_t, uint32_t, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_matmul(void*, const double*, const double*, uint32_t, uint32_t, uint32_t, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_elementwise(void*, const double*, const double*, uint32_t, uint32_t, uint32_t, uint32_t, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_vbx_precompute(void*, const double*, const double*, uint32_t, uint32_t, uint32_t, double*, double*, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_vbx_statistics(void*, const double*, const double*, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, double, double, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_vbx_scores(void*, const double*, const double*, uint32_t, uint32_t, uint32_t, double, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_vbx_prior(void*, const double*, uint32_t, uint32_t, uint32_t, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_vbx_posterior(void*, const double*, const double*, uint32_t, uint32_t, uint32_t, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_vbx_elbo(void*, const double*, uint32_t, uint32_t, uint32_t, uint32_t, double, double, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_vbx_transcendental(void*, const double*, uint32_t, uint32_t, double*, DoubleMetrics*, char*, uint32_t);
extern "C" int wxdouble_vbx_logsumexp(void*, const double*, uint32_t, uint32_t, uint32_t, double*, DoubleMetrics*, char*, uint32_t);
extern "C" void wxdouble_destroy(void*);

int main(int argc, char** argv) {
    assert(argc == 2);
    std::ifstream stream(argv[1]);
    std::string shader((std::istreambuf_iterator<char>(stream)), std::istreambuf_iterator<char>());
    void* context = nullptr;
    char error[128] = {};
    DoubleMetrics metrics = {};
    double input[] = {3., 4.}, output[] = {91., 92.};
    assert(wxdouble_create(shader.data(), shader.size(), nullptr, error, sizeof(error)) != 0);
    assert(wxdouble_create(nullptr, 0, &context, error, sizeof(error)) != 0 && context == nullptr);
    assert(wxdouble_create(shader.data(), shader.size(), &context, error, sizeof(error)) == 0 && context != nullptr);
    assert(wxdouble_normalize(context, input, 1, 2, 0, output, &metrics, error, sizeof(error)) == 0);
    assert(output[0] == .6 && output[1] == .8 && metrics.version == 1 && metrics.kernels == 1);
    output[0] = 91.; output[1] = 92.;
    assert(wxdouble_normalize(context, input, 0, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_normalize(context, input, 1, 1025, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_normalize(context, nullptr, 1, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_normalize(context, input, 1, 2, 0, nullptr, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_normalize(context, input, 1, 2, 0, output, nullptr, error, sizeof(error)) != 0);
    assert(wxdouble_normalize(nullptr, input, 1, 2, 0, output, &metrics, nullptr, 0) != 0);
    input[0] = input[1] = 0.;
    assert(wxdouble_normalize(context, input, 1, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    input[0] = std::numeric_limits<double>::infinity();
    assert(wxdouble_normalize(context, input, 1, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(output[0] == 91. && output[1] == 92.);
    input[0] = 3.; input[1] = 4.;
    assert(wxdouble_normalize(context, input, 1, 2, 0, output, &metrics, error, sizeof(error)) == 0);
    input[0] = 3.; input[1] = 4.;
    double right[] = {2., -1.};
    assert(wxdouble_matmul(context, input, right, 1, 2, 1, output, &metrics, error, sizeof(error)) == 0 && output[0] == 2.);
    output[0] = 91.;
    assert(wxdouble_matmul(context, input, right, 1, 1025, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_matmul(context, input, right, 4096, 1024, 9, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_matmul(nullptr, input, right, 1, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_matmul(context, nullptr, right, 1, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_matmul(context, input, nullptr, 1, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_matmul(context, input, right, 1, 2, 1, nullptr, &metrics, error, sizeof(error)) != 0);
    assert(output[0] == 91.);
    double mean[] = {1., 2.};
    assert(wxdouble_elementwise(context, input, mean, 1, 2, 0, 0, output, &metrics, error, sizeof(error)) == 0 && output[0] == 2. && output[1] == 2.);
    assert(wxdouble_elementwise(context, input, nullptr, 1, 2, 1, 2, output, &metrics, error, sizeof(error)) == 0 && output[0] == 3. * std::sqrt(2.));
    output[0] = 91.;
    assert(wxdouble_elementwise(context, input, nullptr, 1, 2, 0, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_elementwise(context, input, mean, 1, 2, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_elementwise(context, input, nullptr, 1, 2, 1, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_elementwise(context, input, nullptr, 1, 2, 1, 1025, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_elementwise(context, input, mean, 1, 2, 1, 2, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_elementwise(context, nullptr, mean, 1, 2, 0, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_elementwise(context, input, mean, 1, 1025, 0, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(output[0] == 91.);
    double phi[] = {4., 9.}, g[] = {91.}, v[] = {92., 93.}, rho[] = {94., 95.};
    assert(wxdouble_vbx_precompute(context, input, phi, 1, 2, 0, g, v, rho, &metrics, error, sizeof(error)) == 0);
    assert(v[0] == 2. && v[1] == 3. && rho[0] == 6. && rho[1] == 12. && g[0] < 0 && metrics.kernels == 2);
    g[0] = 91.; v[0] = 92.; rho[0] = 94.;
    assert(wxdouble_vbx_precompute(context, input, phi, 1, 1025, 0, g, v, rho, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_precompute(context, input, phi, 1, 2, 2, g, v, rho, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_precompute(context, input, phi, 1, 2, 0, nullptr, v, rho, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_precompute(context, input, phi, 1, 2, 0, g, nullptr, rho, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_precompute(context, input, phi, 1, 2, 0, g, v, nullptr, &metrics, error, sizeof(error)) != 0);
    phi[0] = -1.;
    assert(wxdouble_vbx_precompute(context, input, phi, 1, 2, 0, g, v, rho, &metrics, error, sizeof(error)) != 0);
    phi[0] = 4.;
    assert(g[0] == 91. && v[0] == 92. && rho[0] == 94.);
    double gamma[] = {.25, .75}, stats[] = {2., -0.};
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 2, 0, 1, 1., 1., output, &metrics, error, sizeof(error)) == 0);
    assert(output[0] == .2 && output[1] == .1 && metrics.kernels == 2);
    assert(wxdouble_vbx_statistics(context, output, stats, 1, 2, 2, 1, 1, 1., 1., output, &metrics, error, sizeof(error)) == 0);
    assert(output[0] == .4 && output[1] == 0. && std::signbit(output[1]) && metrics.kernels == 1);
    output[0] = 91.; output[1] = 92.;
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1025, 2, 2, 0, 1, 1., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 4097, 2, 0, 1, 1., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 1025, 0, 1, 1., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 2, 2, 1, 1., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 2, 0, 2, 1., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 1, 1, 1, 1., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, nullptr, phi, 1, 2, 2, 0, 1, 1., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, nullptr, 1, 2, 2, 0, 1, 1., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 2, 0, 1, 1., 1., nullptr, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 2, 0, 1, 0., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 2, 0, 1, 1., 0., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(nullptr, gamma, phi, 1, 2, 2, 0, 1, 1., 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 2, 0, 1, 1., 1., output, nullptr, error, sizeof(error)) != 0);
    assert(output[0] == 91. && output[1] == 92.);
    double inv_l[] = {.5, 1.}, alpha[] = {2., -0.}, packed[] = {2., 4., -.5};
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1, 2, 0, 1., output, &metrics, error, sizeof(error)) == 0);
    assert(output[0] == 4.5 && output[1] == 1. && metrics.kernels == 1);
    assert(wxdouble_vbx_scores(context, output, packed, 1, 2, 1, .5, output, &metrics, error, sizeof(error)) == 0);
    assert(output[0] == 1.5 && output[1] == -.75);
    output[0] = 91.; output[1] = 92.;
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 0, 2, 0, 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1025, 2, 0, 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, inv_l, packed, 4097, 2, 1, 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1, 1025, 0, 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1, 2, 2, 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1, 2, 0, .5, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, inv_l, packed, 1, 2, 1, 0., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(nullptr, inv_l, alpha, 1, 2, 0, 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, nullptr, alpha, 1, 2, 0, 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, inv_l, nullptr, 1, 2, 0, 1., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1, 2, 0, 1., nullptr, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1, 2, 0, 1., output, nullptr, error, sizeof(error)) != 0);
    inv_l[0] = -1.;
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1, 2, 0, 1., output, &metrics, error, sizeof(error)) != 0);
    inv_l[0] = .5;
    assert(output[0] == 91. && output[1] == 92.);
    double prior_gamma[] = {.25, .75, .5, .5};
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 2, 1, output, &metrics, error, sizeof(error)) == 0);
    assert(output[0] == .5 && output[1] == .5 && metrics.kernels == 2);
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 2, 0, prior_gamma, &metrics, error, sizeof(error)) == 0 && prior_gamma[0] == .5 && prior_gamma[1] == .5);
    output[0] = 91.; output[1] = 92.;
    assert(wxdouble_vbx_prior(context, prior_gamma, 0, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_prior(context, prior_gamma, 1025, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 4097, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 2, 2, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_prior(nullptr, prior_gamma, 2, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_prior(context, nullptr, 2, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 2, 1, nullptr, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 2, 1, output, nullptr, error, sizeof(error)) != 0);
    for (double& value : prior_gamma) value = 0.;
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    prior_gamma[0] = -1.;
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    prior_gamma[0] = 1.;
    assert(output[0] == 91. && output[1] == 92.);
    assert(wxdouble_vbx_posterior(context, input, mean, 1, 2, 0, output, &metrics, error, sizeof(error)) == 0 && output[0] == 4. && output[1] == 6.);
    assert(wxdouble_vbx_posterior(context, output, mean, 1, 2, 1, output, &metrics, error, sizeof(error)) == 0 && output[0] == 3. && output[1] == 5.);
    output[0] = 91.; output[1] = 92.;
    assert(wxdouble_vbx_posterior(context, input, mean, 4097, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_posterior(context, input, mean, 1, 1025, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_posterior(context, input, mean, 1, 2, 2, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_posterior(context, nullptr, mean, 1, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_posterior(context, input, nullptr, 1, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_posterior(context, input, mean, 1, 2, 0, nullptr, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_posterior(nullptr, input, mean, 1, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_posterior(context, input, mean, 1, 2, 0, output, nullptr, error, sizeof(error)) != 0);
    assert(output[0] == 91. && output[1] == 92.);
    double elbo_packed[] = {0., 0., 1., 1., 0., 0.};
    assert(wxdouble_vbx_elbo(context, input, 1, 2, 0, 0, 1., 0., output, &metrics, error, sizeof(error)) == 0 && output[0] == 7. && metrics.kernels == 1);
    assert(wxdouble_vbx_elbo(context, elbo_packed, 1, 2, 1, 0, .8, -3., elbo_packed, &metrics, error, sizeof(error)) == 0 && elbo_packed[0] == -3. && metrics.kernels == 2);
    elbo_packed[0] = 0.; output[0] = 91.;
    assert(wxdouble_vbx_elbo(context, input, 1, 4097, 0, 0, 1., 0., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_elbo(context, elbo_packed, 1025, 2, 1, 0, .8, -3., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_elbo(context, elbo_packed, 1, 1025, 1, 0, .8, -3., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_elbo(context, elbo_packed, 1, 2, 1, 2, .8, -3., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_elbo(context, elbo_packed, 1, 2, 2, 0, .8, -3., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_elbo(context, elbo_packed, 1, 2, 1, 0, 0., -3., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_elbo(nullptr, input, 1, 2, 0, 0, 1., 0., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_elbo(context, nullptr, 1, 2, 0, 0, 1., 0., output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_elbo(context, input, 1, 2, 0, 0, 1., 0., nullptr, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_elbo(context, input, 1, 2, 0, 0, 1., 0., output, nullptr, error, sizeof(error)) != 0);
    elbo_packed[2] = 0.;
    assert(wxdouble_vbx_elbo(context, elbo_packed, 1, 2, 1, 0, .8, -3., output, &metrics, error, sizeof(error)) != 0);
    elbo_packed[2] = 1.;
    assert(output[0] == 91.);
    double math_input[] = {1., 2.};
    assert(wxdouble_vbx_transcendental(context, math_input, 2, 0, math_input, &metrics, error, sizeof(error)) == 0 && math_input[0] == 0. && std::abs(math_input[1] - std::log(2.)) < 1e-15);
    math_input[0] = -1.; math_input[1] = 0.;
    assert(wxdouble_vbx_transcendental(context, math_input, 2, 1, output, &metrics, error, sizeof(error)) == 0 && std::abs(output[0] - std::exp(-1.)) < 1e-15 && output[1] == 1.);
    output[0] = 91.;
    assert(wxdouble_vbx_transcendental(context, math_input, 65537, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_transcendental(context, math_input, 0, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_transcendental(context, math_input, 2, 2, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_transcendental(context, math_input, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_transcendental(nullptr, math_input, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_transcendental(context, nullptr, 2, 1, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_transcendental(context, math_input, 2, 1, nullptr, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_transcendental(context, math_input, 2, 1, output, nullptr, error, sizeof(error)) != 0);
    assert(output[0] == 91.);
    double lse_input[] = {0., 0., 1., 1.};
    assert(wxdouble_vbx_logsumexp(context, lse_input, 2, 2, 0, output, &metrics, error, sizeof(error)) == 0);
    assert(std::abs(output[0] - std::log(2.)) < 1e-15 && std::abs(output[1] - (1. + std::log(2.))) < 1e-15 && metrics.kernels == 2);
    assert(wxdouble_vbx_logsumexp(context, lse_input, 2, 2, 1, lse_input, &metrics, error, sizeof(error)) == 0);
    output[0] = 91.; output[1] = 92.;
    lse_input[0] = 1.; lse_input[1] = 2.; lse_input[2] = 0.; lse_input[3] = -61.;
    assert(wxdouble_vbx_logsumexp(context, lse_input, 2, 2, 0, output, &metrics, error, sizeof(error)) != 0 && output[0] == 91. && output[1] == 92.);
    assert(wxdouble_vbx_logsumexp(context, lse_input, 65, 1024, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_logsumexp(context, lse_input, 4097, 1, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_logsumexp(context, lse_input, 1, 1025, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_logsumexp(context, lse_input, 2, 2, 2, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_logsumexp(nullptr, lse_input, 2, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_logsumexp(context, nullptr, 2, 2, 0, output, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_logsumexp(context, lse_input, 2, 2, 0, nullptr, &metrics, error, sizeof(error)) != 0);
    assert(wxdouble_vbx_logsumexp(context, lse_input, 2, 2, 0, output, nullptr, error, sizeof(error)) != 0);
    assert(output[0] == 91. && output[1] == 92.);
    wxdouble_destroy(context);
    wxdouble_destroy(nullptr);
    std::string legacy_shader = shader.substr(0, shader.find("\nstruct MatrixDimensions"));
    context = nullptr;
    assert(wxdouble_create(legacy_shader.data(), legacy_shader.size(), &context, error, sizeof(error)) == 0 && context != nullptr);
    assert(wxdouble_normalize(context, input, 1, 2, 0, output, &metrics, error, sizeof(error)) == 0 && output[0] == .6 && output[1] == .8);
    output[0] = 91.;
    assert(wxdouble_matmul(context, input, right, 1, 2, 1, output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    assert(wxdouble_elementwise(context, input, nullptr, 1, 2, 1, 2, output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    wxdouble_destroy(context);
    std::string precompute_shader = shader.substr(0, shader.find("\nstruct StatisticsDimensions"));
    assert(wxdouble_create(precompute_shader.data(), precompute_shader.size(), &context, error, sizeof(error)) == 0);
    assert(wxdouble_vbx_precompute(context, input, phi, 1, 2, 0, g, v, rho, &metrics, error, sizeof(error)) == 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 2, 0, 1, 1., 1., output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    wxdouble_destroy(context);
    g[0] = 91.;
    std::string statistics_shader = shader.substr(0, shader.find("\nstruct ScoreDimensions"));
    assert(wxdouble_create(statistics_shader.data(), statistics_shader.size(), &context, error, sizeof(error)) == 0);
    assert(wxdouble_vbx_statistics(context, gamma, phi, 1, 2, 2, 0, 1, 1., 1., output, &metrics, error, sizeof(error)) == 0);
    output[0] = 91.;
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1, 2, 0, 1., output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    wxdouble_destroy(context);
    std::string scores_shader = shader.substr(0, shader.find("\nkernel void double_vbx_prior"));
    assert(wxdouble_create(scores_shader.data(), scores_shader.size(), &context, error, sizeof(error)) == 0);
    assert(wxdouble_vbx_scores(context, inv_l, alpha, 1, 2, 0, 1., output, &metrics, error, sizeof(error)) == 0);
    output[0] = 91.;
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 2, 1, output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    wxdouble_destroy(context);
    std::string prior_shader = shader.substr(0, shader.find("\nkernel void double_vbx_posterior"));
    assert(wxdouble_create(prior_shader.data(), prior_shader.size(), &context, error, sizeof(error)) == 0);
    assert(wxdouble_vbx_prior(context, prior_gamma, 2, 2, 1, output, &metrics, error, sizeof(error)) == 0);
    output[0] = 91.;
    assert(wxdouble_vbx_posterior(context, input, mean, 1, 2, 0, output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    wxdouble_destroy(context);
    std::string posterior_shader = shader.substr(0, shader.find("\n// Signed reductions reproduce"));
    assert(wxdouble_create(posterior_shader.data(), posterior_shader.size(), &context, error, sizeof(error)) == 0);
    assert(wxdouble_vbx_posterior(context, input, mean, 1, 2, 0, output, &metrics, error, sizeof(error)) == 0);
    output[0] = 91.;
    assert(wxdouble_vbx_elbo(context, input, 1, 2, 0, 0, 1., 0., output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    wxdouble_destroy(context);
    std::string elbo_shader = shader.substr(0, shader.find("\n// Algorithms adapted from OpenLibm"));
    assert(wxdouble_create(elbo_shader.data(), elbo_shader.size(), &context, error, sizeof(error)) == 0);
    assert(wxdouble_vbx_elbo(context, input, 1, 2, 0, 0, 1., 0., output, &metrics, error, sizeof(error)) == 0);
    output[0] = 91.;
    assert(wxdouble_vbx_transcendental(context, math_input, 2, 1, output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    wxdouble_destroy(context);
    std::string math_shader = shader.substr(0, shader.find("\n// The finite nonnegative log1p specialization"));
    assert(wxdouble_create(math_shader.data(), math_shader.size(), &context, error, sizeof(error)) == 0);
    assert(wxdouble_vbx_transcendental(context, input, 2, 0, output, &metrics, error, sizeof(error)) == 0);
    output[0] = 91.;
    assert(wxdouble_vbx_logsumexp(context, input, 1, 2, 0, output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    assert(wxdouble_vbx_transcendental(context, input, 2, 2, output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    wxdouble_destroy(context);
    std::string matrix_shader = shader.substr(0, shader.find("\nstruct ElementDimensions"));
    context = nullptr;
    assert(wxdouble_create(matrix_shader.data(), matrix_shader.size(), &context, error, sizeof(error)) == 0 && context != nullptr);
    assert(wxdouble_matmul(context, input, right, 1, 2, 1, output, &metrics, error, sizeof(error)) == 0 && output[0] == 2.);
    output[0] = 91.;
    assert(wxdouble_elementwise(context, input, nullptr, 1, 2, 1, 2, output, &metrics, error, sizeof(error)) != 0 && output[0] == 91.);
    assert(wxdouble_vbx_precompute(context, input, phi, 1, 2, 0, g, v, rho, &metrics, error, sizeof(error)) != 0 && g[0] == 91.);
    wxdouble_destroy(context);
}
